script=r'''let playing=true,loop=true,speed=1,mode='sequence',last=0;const views=data.map(()=>({n:0,time:0,done:false})),cache=new Map;let ready=false;
function framesFor(i){const c=data[i];return (c.kind==='after'||(polish&&c.kind==='before'))&&mode==='sequence'?[...data[0].frames,...c.frames,...data[0].frames]:c.frames}
function load(p){if(!cache.has(p))cache.set(p,new Promise((yes,no)=>{const im=new Image;im.onload=()=>yes(im);im.onerror=()=>no(Error('Imagem ausente: '+p));im.src=p}));return cache.get(p)}
async function draw(i){const fs=framesFor(i),v=views[i];v.n=Math.min(v.n,fs.length-1);const f=fs[v.n],im=await load(f.png),ctx=document.getElementById('anim-'+i).getContext('2d');document.getElementById('anim-'+i).style.outline=f.impact?'2px solid #e2b659':'none';ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,256,256);ctx.drawImage(im,0,0);document.getElementById('info-'+i).textContent=(v.n+1)+'/'+fs.length+' · '+f.durationMs+' ms · '+f.phase+(f.impact?' · IMPACTO VISUAL':'')+' · '+(f.weaponVisible?'arma visível':'sem arma');const g=document.getElementById('grip-'+i);if(g){const pos=f.rightGrip||[99,146],gc=g.getContext('2d');gc.imageSmoothingEnabled=false;gc.clearRect(0,0,24,24);gc.drawImage(im,pos[0]-12,pos[1]-12,24,24,0,0,24,24)}}
function reset(){views.forEach((v,i)=>{v.n=0;v.time=0;v.done=false;draw(i)});last=0}
function setMode(m){mode=m;reset()}
function advance(dt){views.forEach((v,i)=>{if(v.done)return;const fs=framesFor(i);v.time+=dt;let changed=false;while(v.time>=fs[v.n].durationMs&&!v.done){v.time-=fs[v.n].durationMs;if(v.n===fs.length-1){if(loop)v.n=0;else{v.done=true;v.time=0}}else v.n++;changed=true}if(changed)draw(i)})}
document.getElementById('play').onclick=()=>{playing=!playing;document.getElementById('play').textContent=playing?'Pausar':'Reproduzir'};
document.getElementById('reset').onclick=reset;document.getElementById('step').onclick=()=>{playing=false;document.getElementById('play').textContent='Reproduzir';views.forEach((v,i)=>{v.done=false;v.n=Math.min(v.n+1,framesFor(i).length-1);v.time=0;draw(i)})};
document.getElementById('speed').onchange=e=>speed=Number(e.target.value);document.getElementById('mode').onchange=e=>setMode(e.target.value);document.getElementById('loop').onchange=e=>{loop=e.target.checked;views.forEach(v=>v.done=false)};
document.getElementById('zoom').onchange=e=>{const z=Number(e.target.value);document.querySelectorAll('.stage canvas').forEach(c=>c.style.width=c.style.height=(256*z)+'px');document.querySelectorAll('.stage').forEach(s=>s.style.height=(256*z+24)+'px')};document.getElementById('bg').onchange=e=>document.body.className=e.target.value;
Promise.all(data.flatMap(c=>c.frames.map(f=>load(f.png)))).then(()=>Promise.all(data.map((_,i)=>draw(i)))).then(()=>{ready=true;document.body.dataset.ready='true'});function tick(t){const dt=last?Math.min(100,t-last)*speed:0;last=t;if(ready&&playing)advance(dt);requestAnimationFrame(tick)}requestAnimationFrame(tick);'''
